WITH cleaned AS (SELECT *, FLOOR(salary) AS salary_whole, COALESCE(full_name, 'N/A') AS full_name_filled FROM employees WHERE level IS NOT DISTINCT FROM 'L5' AND hire_date >= TO_DATE('2023-08-15')) SELECT CASE WHEN salary >= 148000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, COUNT(CASE WHEN job_title = 'Engineer' THEN 1 END) AS engineer_count, COUNT_IF(level = 'L5') AS l5_events, PERCENTILE_APPROX(salary_whole, 0.9) AS salary_whole_p90, SIZE(COLLECT_SET(level)) AS num_levels FROM cleaned GROUP BY ROLLUP (CASE WHEN salary >= 148000 THEN 'HIGH' ELSE 'LOW' END) ORDER BY salary_tier DESC NULLS FIRST;
